package com.globalisosecurity.backend.controllers;
import com.globalisosecurity.backend.dto.FirmaCreateRequest;import com.globalisosecurity.backend.models.Firma;import com.globalisosecurity.backend.services.FirmaService;import java.util.List;import org.springframework.http.ResponseEntity;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/firmas")
public class FirmaController{private final FirmaService service;public FirmaController(FirmaService service){this.service=service;}
 @GetMapping public List<Firma> todas(){return service.obtenerTodas();}@GetMapping("/{id}") public ResponseEntity<?> una(@PathVariable Long id){return service.obtenerPorId(id).<ResponseEntity<?>>map(ResponseEntity::ok).orElseGet(()->ResponseEntity.notFound().build());}@GetMapping("/estado/{estado}") public List<Firma> estado(@PathVariable String estado){return service.obtenerPorEstado(estado);}@GetMapping("/servicio/{id}") public List<Firma> servicio(@PathVariable Long id){return service.obtenerPorServicio(id);}@GetMapping("/empresa/{id}") public List<Firma> empresa(@PathVariable Long id){return service.obtenerPorEmpresa(id);}
 @PostMapping @PreAuthorize("hasAnyRole('ADMINISTRADOR','IMPLEMENTADOR','AUDITOR','USUARIO_EMPRESA','USUARIO')") public Firma crear(@RequestBody FirmaCreateRequest r){return service.crearFirma(r);}@PutMapping("/{id}") @PreAuthorize("hasAnyRole('ADMINISTRADOR','AUDITOR')") public Firma actualizar(@PathVariable Long id,@RequestBody Firma f){return service.actualizarFirma(id,f);}@DeleteMapping("/{id}") @PreAuthorize("hasRole('ADMINISTRADOR')") public void eliminar(@PathVariable Long id){service.eliminarFirma(id);}}
